gin:0}dt{color:var(--color-performance-muted)}@media(max-width:760px){main{padding:20px}section{grid-template-columns:1fr;gap:20px}.intro{padding:32px 0}.inverse{padding:20px}.cards{grid-template-columns:1fr}}@media(max-width:380px){main{padding:16px}header{gap:12px}}

